 own={(r+dr,c+dc) for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]}
 for dr,dc,target in [(0,1,horizontal),(0,-1,horizontal),(1,0,vertical),(-1,0,vertical)]:
